import json, glob, os, sys
from phasemap.config import RULESET_VERSION
from phasemap.output.writer import validate_published
files = glob.glob("public/data/phasemap/*/latest.json")
if not files:
    print("SCHEMA GATE FAILED: no snapshots written"); sys.exit(1)
bad = []
for f in files:
    try:
        slim = json.load(open(f, encoding="utf-8"))
        nf = os.path.join(os.path.dirname(f), "narrations.json")
        narr = json.load(open(nf, encoding="utf-8")) if os.path.exists(nf) else None
        validate_published(slim, narr)
        if slim["ruleset_version"] != RULESET_VERSION:
            bad.append(f"{f}: ruleset {slim['ruleset_version']} != {RULESET_VERSION}")
    except Exception as e:
        bad.append(f"{f}: {e}")
if bad:
    print("SCHEMA GATE FAILED:"); [print(" -", b) for b in bad]; sys.exit(1)
print(f"schema gate OK - {len(files)} published snapshots at ruleset v{RULESET_VERSION}")
